int handle_scsi_command(SCSIDiskReq *r) {
    if (r == NULL || r->cmd == NULL) {
        return -1;
    }

    // Check if this is a tray load/eject operation
    if (r->cmd[0] == 0x1B && (r->cmd[4] & 0x02)) {
        // Eject operation
        if (r->device_type == SCSI_ROM && (r->cmd[4] & 0x01)) {
            // Perform eject
            if (perform_eject(r)) {
                return -1;
            }
        } else {
            return -1;
        }
    }

    // Check if the transfer length is valid
    if (r->data_length > MAX_TRANSFER_LENGTH) {
        return -1;
    }

    // Handle specific command types
    if (r->cmd[0] == 0x00) {
        // Unit ready check
        check_unit_ready(r);
    } else if (r->cmd[0] == 0x25) {
        // Tray open status
        check_tray_status(r);
    } else {
        // Unrecognized command
        return -1;
    }

    return 0;
}

int handle_scsi_command(SCSIDiskReq *r) {
    if (r == NULL) {
        return -1;
    }

    if (r->command[0] == SCSI_EJECT) {
        if (r->device_type == SCSI_ROM && (r->command[1] & 0x01)) {
            if (eject_tray(r) != 0) {
                return -1;
            }
        }
    } else if (r->command[0] == SCSI_TEST_UNIT_READY) {
        if (tray_is_open(r)) {
            return -1;
        }
    } else if (r->command[0] == SCSI_INQUIRY) {
        if (r->data_length > MAX_INQUIRY_SIZE) {
            return -1;
        }
    } else {
        return -1;
    }

    if (r->data_transfer_length > MAX_TRANSFER_SIZE) {
        return -1;
    }

    return 0;
}

int scsi_emulate_command(SCSIDiskReq *r) {
    if (r->command[0] == GPCDB && r->command[1] == 0x22) {
        if (r->command[3] & 0x01) {
            if (r->device_type == ROM_TYPE_DEVICE) {
                if (r->tray_state == EJECT_REQUESTED) {
                    r->tray_state = TRAY_EJECTED;
                } else {
                    return -1;
                }
            } else {
                return -1;
            }
        } else {
            if (r->unit_state != UNIT_READY) {
                return -1;
            }
        }
    }

    if (r->data_transfer_length > MAX_TRANSFER_LENGTH) {
        return -1;
    }

    return 0;
}

int handle_scsi_command(SCSIDiskReq* r) {
    if (r == NULL) {
        return -1;
    }

    if (r->command[0] == SCSI_EJECT) {
        if (r->device_type == SCSI_ROM) {
            // Perform eject operation
            if (r->command[1] & SCSI_EJECT_TRAY) {
                if (r->tray_locked) {
                    return -1; // Tray is locked
                }
                r->tray_open = 1;
            } else if (r->command[1] & SCSI_EJECT_LOAD) {
                if (r->tray_open) {
                    r->tray_open = 0;
                }
            }
        } else {
            // Eject not supported for non-ROM devices
            return -1;
        }
        return 0;
    }

    if (r->command[0] == SCSI_TEST_UNIT_READY) {
        if (r->tray_open) {
            return -1; // Unit not ready because tray is open
        }
        return 0;
    }

    if (r->command[0] == SCSI_INQUIRY) {
        if (r->data_length < r->inquiry_data_len) {
            // Invalid transfer length
            return -1;
        }
        // Copy inquiry data to the data buffer
        memcpy(r->data, r->inquiry_data, r->inquiry_data_len);
        return 0;
    }

    // Handle other commands or consider them as invalid
    return -1;
}

int SCSIDiskEmulateCommand(SCSIDiskReq *r) {
    // Check for load/eject operation
    if (r->cmd[0] == GPCMD_START_STOP_UNIT) {
        if (r->cmd[4] & 0x01) { // Eject condition
            if (r->deviceType == SCSI_DEVICE_ROM) {
                // Perform eject operation
                if (r->trayLocked) {
                    return -1; // Tray is locked, cannot eject
                }
                r->trayOpen = 1;
            }
        } else {
            // Load operation
            r->trayOpen = 0;
        }
        return 0;
    }

    // Check if the command is to check unit readiness
    if (r->cmd[0] == GPCMD_TEST_UNIT_READY) {
        if (r->trayOpen) {
            return -1; // Unit not ready as tray is open
        }
        return 0;
    }

    // Check for illegal requests or invalid command types
    if (r->cmd[0] != GPCMD_REQUEST_SENSE && r->cmd[0] != GPCMD_INQUIRY) {
        if (r->transferLength > MAX_SCSI_TRANSFER) {
            return -1; // Exceeds allowed transfer length
        }
    }

    return -1; // Illegal or unsupported command
}
